-- Store every instant as timestamptz rather than a naive timestamp.
--
-- A 'timestamp without time zone' column means whatever the writer thought
-- it meant. The application wrote UTC; anything writing through psql or a
-- trigger wrote local time, and the two were 5h30m apart with nothing to
-- distinguish them. For an audit trail whose entire value is being able to
-- say when something happened, that is a correctness bug.
--
-- USING ... AT TIME ZONE 'UTC' reads the existing naive values as the UTC
-- they were intended to be, so no stored instant moves.

ALTER TABLE approval_requests ALTER COLUMN "appliedAt" TYPE timestamptz(3) USING "appliedAt" AT TIME ZONE 'UTC';
ALTER TABLE approval_requests ALTER COLUMN "createdAt" TYPE timestamptz(3) USING "createdAt" AT TIME ZONE 'UTC';
